{"function":"async () => {
  const props = ['outline-style','outline-width','outline-color','box-shadow','border-top-color','background-color'];
  const out = {};
  for (const id of ['nome','cpf','servico','unidade','descricao','data-preferencial','declaracao','forma-video']) {
    const el = document.getElementById(id);
    el.blur();
    const s1 = getComputedStyle(el); const before = Object.fromEntries(props.map(p=>[p,s1.getPropertyValue(p)]));
    el.focus({focusVisible:true});
    await new Promise(r=>setTimeout(r,50));
    const s2 = getComputedStyle(el); const after = Object.fromEntries(props.map(p=>[p,s2.getPropertyValue(p)]));
    const diff = props.filter(p=>before[p]!==after[p]).map(p=>p+':'+before[p]+'→'+after[p]);
    out[id] = {diff, fv: el.matches(':focus-visible'), cls: el.className, parentCls: el.parentElement.className};
    el.blur();
  }
  return out;
}"}

