{"function":"async () => {
  const props = ['outline-style','outline-width','outline-color','box-shadow','border-top-color','background-color','text-decoration-line','color'];
  const els = [...document.querySelectorAll('a[href],button:not([disabled]),input,textarea,[tabindex="0"],[role=button]')].filter(e=>e.tabIndex>=0 && e.offsetParent!==null);
  const out=[];
  for (const el of els) {
    if (['nome','cpf','servico','unidade','descricao','data-preferencial'].includes(el.id)) continue;
    el.blur(); await new Promise(r=>setTimeout(r,20));
    const b = getComputedStyle(el); const before = props.map(p=>b.getPropertyValue(p));
    el.focus({focusVisible:true}); await new Promise(r=>setTimeout(r,60));
    const a = getComputedStyle(el); const after = props.map(p=>a.getPropertyValue(p));
    const diff = props.filter((p,i)=>before[i]!==after[i]).map((p,i)=>p+'='+a.getPropertyValue(p));
    out.push((el.id||el.className||el.tagName).toString().slice(0,40)+' fv='+el.matches(':focus-visible')+' :: '+diff.join('; '));
  }
  return out;
}"}
